"""A crowd: hundreds of characters, every motion generated by MotionBricks, in batched calls.

Each character plays its generated motion and, near the motion's transition point, asks its
driver for the next request: walk a gait toward a goal, stand, or step through a Smart
Primitive's sequence. Requests wait up to LOOKAHEAD for one another so batches fill, except
where timing matters (interactions generate exactly at their authored transition points). A
batch runs as soon as any character would otherwise run out of motion, or the batch is full.

Upstream's character runtime does the same for one character with a state machine, springs and
idle clips. Here a character's state is a few numbers and its driver, so a step of the whole
crowd costs about as much as one upstream character.
"""

from __future__ import annotations

import copy
import math
from dataclasses import dataclass
from typing import Callable

import numpy as np

from motionbricks.model.contract import MODEL_SAMPLE_RATE

from .batch import FROM_GAIT, FROM_SEQUENCE, Batch, BatchGenerator, Request, ground_placement, token_bits
from .gaits import Gait, GaitLibrary
from .obstacles import Obstacle, character_properties

# How early a character may ask for its next motion. Generating early only cuts the end off the
# current motion, so the wait fills batches instead of running a model call every tick.
LOOKAHEAD = 0.15
# A walking character re-plans when its way turns by more than this, once its motion has played a little.
STEER_DEGREES = 35.0
MIN_PLAY = 0.35
DEFAULT_TOKEN_BITS = token_bits(range(6, 15))


@dataclass
class Generation:
    """One character's new motion, as listeners hear about it."""

    character: int
    clock: float  # crowd time at which the motion starts to play
    frames: int  # frames at 30 Hz
    transition: int  # frame at which the next motion is due, unless a re-plan comes first
    label: str  # what the character was doing, such as "run" or "vault Jump 2/3"
    request: Request
    row: int  # row in the batch


@dataclass
class CrowdFrame:
    """What a viewer draws: each live character's slot and packed pose."""

    slots: np.ndarray
    packed: np.ndarray


# ---------------------------------------------------------------- drivers


class Driver:
    """Decides a character's next request. exact drivers never generate before the transition point."""

    exact = False
    label = "driver"

    def start(self, crowd: Crowd, character: int) -> None:
        pass

    def update(self, crowd: Crowd, character: int, delta_time: float) -> None:
        pass

    def heading(self, crowd: Crowd, character: int) -> np.ndarray | None:
        """The way the character wants to go on the ground, if it is going somewhere."""
        return None

    def request(self, crowd: Crowd, character: int) -> Request:
        raise NotImplementedError


class Walk(Driver):
    """Move in a gait along a heading or toward a goal, then hand over (by default, stand).

    goal may be an array that someone else moves, such as the point a horde chases.
    """

    def __init__(
        self,
        gait: Gait,
        *,
        heading=None,
        goal=None,
        arrive: float = 0.8,
        distance: float | None = None,
        then: Driver | None = None,
    ) -> None:
        self.gait = gait
        self.direction = None if heading is None else _unit(np.asarray(heading, dtype=np.float64))
        self.goal = goal
        self.arrive = arrive
        self.distance = distance
        self.then = then
        self.label = gait.name
        self.origin = None

    def start(self, crowd: Crowd, character: int) -> None:
        self.origin = crowd.position[character].copy()

    def heading(self, crowd: Crowd, character: int) -> np.ndarray:
        if self.goal is not None:
            offset = np.asarray(self.goal, dtype=np.float64)[:2] - crowd.position[character]
            distance = float(np.linalg.norm(offset))
            return offset / distance if distance > 1e-6 else crowd.heading[character]
        if self.direction is not None:
            return self.direction
        return crowd.heading[character]

    def update(self, crowd: Crowd, character: int, delta_time: float) -> None:
        position = crowd.position[character]
        arrived = self.goal is not None and self.arrive > 0 and np.linalg.norm(np.asarray(self.goal)[:2] - position) < self.arrive
        travelled = self.distance is not None and np.linalg.norm(position - self.origin) >= self.distance
        if arrived or travelled:
            crowd.drive(character, self.then if self.then is not None else Stand())

    def request(self, crowd: Crowd, character: int) -> Request:
        gait = self.gait
        heading = crowd.desired[character]
        ground = crowd.position[character] + heading * gait.lead
        return Request(
            character, FROM_GAIT, gait.index, ground_placement(ground[0], ground[1], heading[0], heading[1]),
            token_bits=gait.token_bits, transition_early=gait.transition_early,
        )


class Stand(Driver):
    """Come to rest and stay there, generating toward the idle target.

    The first target sits a short slide ahead of a moving character, so it stops the way a person
    does rather than on the spot.
    """

    label = "stand"

    def __init__(self, *, heading=None, slide: float = 0.45) -> None:
        self.facing = None if heading is None else _unit(np.asarray(heading, dtype=np.float64))
        self.slide = slide
        self.spot = None

    def start(self, crowd: Crowd, character: int) -> None:
        self.spot = crowd.position[character] + crowd.velocity[character] * self.slide
        if self.facing is None:
            self.facing = crowd.heading[character].copy()

    def request(self, crowd: Crowd, character: int) -> Request:
        idle = crowd.gaits["idle"]
        return Request(
            character, FROM_GAIT, idle.index, ground_placement(self.spot[0], self.spot[1], self.facing[0], self.facing[1]),
            token_bits=idle.token_bits, transition_early=idle.transition_early,
        )


class Interact(Driver):
    """Step through one of an obstacle's sequences, then hand over.

    Without a sequence name, the obstacle picks the one closest to the character's speed.
    """

    exact = True

    def __init__(self, obstacle: Obstacle, *, sequence: str | None = None, then: Driver | None = None) -> None:
        self.obstacle = obstacle
        self.sequence = sequence
        self.then = then
        self.params = ()
        self.step = 0
        self.label = obstacle.kind

    def start(self, crowd: Crowd, character: int) -> None:
        obstacle = self.obstacle
        speed = float(np.linalg.norm(crowd.velocity[character]))
        if self.sequence is not None:
            index = obstacle.runtime.sequence_index(self.sequence)
            if index < 0:
                raise ValueError(f"{obstacle.name} has no sequence {self.sequence!r}.")
        else:
            index = obstacle.sequence_for_speed(speed)
        self.sequence_name = next(name for name, i in obstacle.runtime.asset.sequence_indices_by_name.items() if i == index)
        heading = crowd.heading[character]
        properties = character_properties(crowd.position[character], crowd.velocity[character], heading, max(speed, 0.1))
        self.params = obstacle.write_sequence(index, properties, crowd.generator.sequence_rows(character))
        crowd.sequence_params[character] = self.params
        self.step = 0

    def request(self, crowd: Crowd, character: int) -> Request:
        if self.step >= len(self.params):
            after = self.then if self.then is not None else Stand()
            crowd.drive(character, after, now=False)
            return after.request(crowd, character)
        step = self.step
        self.step += 1
        params = self.params[step]
        self.label = f"{self.obstacle.kind} {self.sequence_name} {step + 1}/{len(self.params)}"
        counts = params.allowed_token_counts
        return Request(
            character, FROM_SEQUENCE, step, num_targets=params.num_poses_to_use,
            token_bits=token_bits(counts) if counts else DEFAULT_TOKEN_BITS,
            transition_early=params.transition_early_by_frames,
        )


class Seated(Driver):
    """Stay in the last pose of the sequence just played (a seat), for a while, then hand over."""

    exact = True
    label = "seated"

    def __init__(self, seconds: float | None = None, *, then: Driver | None = None) -> None:
        self.seconds = seconds
        self.then = then

    def start(self, crowd: Crowd, character: int) -> None:
        self.params = crowd.sequence_params[character]
        self.until = math.inf if self.seconds is None else crowd.clock + self.seconds

    def update(self, crowd: Crowd, character: int, delta_time: float) -> None:
        if crowd.clock >= self.until and self.then is not None:
            crowd.drive(character, self.then, now=False)

    def request(self, crowd: Crowd, character: int) -> Request:
        step = len(self.params) - 1
        params = self.params[step]
        counts = params.allowed_token_counts
        return Request(
            character, FROM_SEQUENCE, step, num_targets=params.num_poses_to_use,
            token_bits=token_bits(counts) if counts else DEFAULT_TOKEN_BITS,
            transition_early=params.transition_early_by_frames,
        )


def sit(obstacle: Obstacle, seconds: float | None = None, then: Driver | None = None) -> Interact:
    """Sit on a seat, stay for seconds (or for good), then stand up and hand over."""
    stand_up = Interact(obstacle, sequence="Stand", then=then) if seconds is not None else None
    return Interact(obstacle, sequence="Sit", then=Seated(seconds, then=stand_up))


class Approach(Walk):
    """Walk to an obstacle and use it as soon as the character's probe box reaches it."""

    def __init__(
        self,
        obstacle: Obstacle,
        gait: Gait,
        *,
        aim=None,
        sequence: str | None = None,
        then: Driver | None = None,
        interaction: Callable[[Obstacle, Driver | None], Driver] | None = None,
    ) -> None:
        super().__init__(gait, goal=np.array(aim if aim is not None else obstacle.position, dtype=np.float64), arrive=0.0)
        self.obstacle = obstacle
        self.sequence = sequence
        self.after = then
        self.interaction = interaction
        self.label = f"{gait.name} to {obstacle.kind}"

    def update(self, crowd: Crowd, character: int, delta_time: float) -> None:
        heading = self.heading(crowd, character)
        if self.obstacle.probe_touches(crowd.position[character], heading, self.gait.speed):
            if self.interaction is not None:
                crowd.drive(character, self.interaction(self.obstacle, self.after))
            else:
                crowd.drive(character, Interact(self.obstacle, sequence=self.sequence, then=self.after))


def _unit(vector: np.ndarray) -> np.ndarray:
    return vector / max(float(np.linalg.norm(vector)), 1e-9)


# ---------------------------------------------------------------- the crowd


class Crowd:
    """Characters that share one BatchGenerator."""

    def __init__(
        self,
        generator: BatchGenerator,
        gaits: GaitLibrary,
        *,
        lookahead: float = LOOKAHEAD,
        steer_degrees: float = STEER_DEGREES,
        separation: float = 0.0,
        footprints=(),
        keep: bool = False,
    ) -> None:
        self.generator = generator
        self.gaits = gaits
        generator.set_gait_targets(gaits.targets)
        self.lookahead = lookahead
        self.steer_cos = math.cos(math.radians(steer_degrees))
        self.separation = separation
        self.footprints = footprints
        self.keep = keep
        Z = generator.capacity
        self.capacity = Z
        self.alive = np.zeros(Z, dtype=bool)
        self.time = np.zeros(Z, dtype=np.float32)  # playback time in the current motion
        self.transition = np.zeros(Z, dtype=np.float32)  # playback time of its transition point
        self.position = np.zeros((Z, 2), dtype=np.float64)
        self.velocity = np.zeros((Z, 2), dtype=np.float64)
        self.heading = np.tile(np.array([1.0, 0.0]), (Z, 1))  # the way the character faces
        self.planned = self.heading.copy()  # the heading its current motion was planned for
        self.desired = self.heading.copy()
        self.replan = np.zeros(Z, dtype=bool)
        self.drivers: list[Driver | None] = [None] * Z
        self.sequence_params: list[tuple] = [()] * Z
        self.listeners: list[Callable[[list[Generation], Batch], None]] = []
        self.clock = 0.0
        self.batches: list[tuple[float, int, float]] = []  # (clock, requests, GPU ms)

    # ------------------------------------------------------------ characters

    @property
    def count(self) -> int:
        return int(self.alive.sum())

    def spawn(self, position, heading=(1.0, 0.0), driver: Driver | None = None) -> int:
        """Stand a new character in the idle pose, facing a heading. Returns its slot."""
        free = np.flatnonzero(~self.alive)
        if not len(free):
            raise RuntimeError("The crowd is full.")
        character = int(free[0])
        heading = _unit(np.asarray(heading, dtype=np.float64))
        idle = self.gaits["idle"]
        self.generator.seed(character, self.gaits.targets[idle.index][0], ground_placement(position[0], position[1], heading[0], heading[1]))
        self.alive[character] = True
        self.time[character] = 0.0
        self.transition[character] = 0.0
        self.position[character] = position[:2]
        self.velocity[character] = 0.0
        self.heading[character] = heading
        self.planned[character] = heading
        self.desired[character] = heading
        self.replan[character] = False
        self.drive(character, driver if driver is not None else Stand(), now=False)
        return character

    def fork(self, character: int, count: int) -> list[int]:
        """Copy a character, motion and all, into count new slots: futures that share one past."""
        free = [int(i) for i in np.flatnonzero(~self.alive)[:count]]
        if len(free) < count:
            raise RuntimeError("The crowd is full.")
        self.generator.copy(character, free)
        for slot in free:
            for array in (self.time, self.transition, self.position, self.velocity, self.heading, self.planned, self.desired):
                array[slot] = array[character]
            self.alive[slot] = True
            self.replan[slot] = self.replan[character]
            self.sequence_params[slot] = self.sequence_params[character]
            self.drivers[slot] = copy.copy(self.drivers[character])
        return free

    def drive(self, character: int, driver: Driver, *, now: bool = True) -> None:
        """Hand a character to a driver. now=True generates its next motion on the next step."""
        self.drivers[character] = driver
        driver.start(self, character)
        if now:
            self.replan[character] = True

    def remove(self, character: int) -> None:
        self.alive[character] = False
        self.drivers[character] = None

    def clear(self) -> None:
        for character in np.flatnonzero(self.alive):
            self.remove(int(character))

    # ------------------------------------------------------------ stepping

    def step(self, delta_time: float) -> CrowdFrame:
        """Advance every character, generate for those that need it, and return the poses to draw."""
        live = self.alive.copy()
        self.clock += delta_time
        self.time[live] += delta_time
        for character in np.flatnonzero(live):
            driver = self.drivers[character]
            if driver is not None:
                driver.update(self, int(character), delta_time)
        steerable = self._desired_headings(live)
        exact = np.array([bool(d is not None and d.exact) for d in self.drivers])
        early = np.where(exact, 0.0, self.lookahead)
        overshoot = self.time - self.transition
        due = live & (overshoot >= -early)
        urgent = live & ((overshoot >= -delta_time) | self.replan)
        turned = live & steerable & ~exact & (np.einsum("ij,ij->i", self.desired, self.planned) < self.steer_cos)
        steer = live & ~due & ~urgent & turned & (self.time > MIN_PLAY)
        order = np.concatenate([
            np.flatnonzero(urgent)[np.argsort(-overshoot[urgent], kind="stable")],
            np.flatnonzero(due & ~urgent)[np.argsort(-overshoot[due & ~urgent], kind="stable")],
            np.flatnonzero(steer),
        ])[: self.generator.batch]
        if urgent.any() or len(order) >= self.generator.batch:
            self._generate([int(c) for c in order])
        packed = self.generator.sample(self.time)
        moved = packed[:, :2].astype(np.float64)
        ease = 1.0 - math.exp(-delta_time / 0.15)
        instant = (moved - self.position) / max(delta_time, 1e-6)
        self.velocity[live] += (instant[live] - self.velocity[live]) * ease
        self.position[live] = moved[live]
        speed = np.linalg.norm(self.velocity, axis=1)
        facing = live & (speed > 0.5)
        self.heading[facing] = self.velocity[facing] / speed[facing, None]
        slots = np.flatnonzero(self.alive)
        return CrowdFrame(slots=slots.astype(np.uint16), packed=packed[slots])

    def _desired_headings(self, live: np.ndarray) -> np.ndarray:
        """Each driver's heading, then (if set up) pushed apart from neighbours and out of obstacles."""
        steerable = np.zeros(self.capacity, dtype=bool)
        desired = self.planned.copy()
        for character in np.flatnonzero(live):
            driver = self.drivers[character]
            heading = driver.heading(self, int(character)) if driver is not None else None
            if heading is not None:
                desired[character] = heading
                steerable[character] = True
        movers = np.flatnonzero(steerable)
        if len(movers) and (self.separation > 0 or self.footprints):
            positions = self.position[movers]
            heading = desired[movers]
            if self.separation > 0:
                others = self.position[np.flatnonzero(live)]
                offsets = positions[:, None, :] - others[None, :, :]
                gaps = np.linalg.norm(offsets, axis=2)
                gaps = np.where(gaps < 1e-6, 1e6, gaps)
                push = np.where(gaps[..., None] < self.separation, offsets / gaps[..., None] ** 2, 0.0).sum(axis=1)
                heading = heading + 0.7 * push
            for box in self.footprints:
                offset = positions - box.center
                local = np.stack([offset @ box.axis_x, offset @ box.axis_y], axis=1)
                gaps_box = np.abs(local) - box.half
                near = np.max(gaps_box, axis=1) < 1.0
                if not near.any():
                    continue
                axis = np.argmax(gaps_box, axis=1)
                normal = np.where(axis[:, None] == 0, box.axis_x[None, :], box.axis_y[None, :]) * np.sign(
                    np.take_along_axis(local, axis[:, None], axis=1)
                )
                heading[near] += 1.2 * normal[near]
            desired[movers] = heading
        norms = np.linalg.norm(desired, axis=1, keepdims=True)
        self.desired = np.where(norms > 1e-9, desired / np.maximum(norms, 1e-9), self.heading)
        return steerable

    def _generate(self, characters: list[int]) -> None:
        requests = []
        labels = []
        for character in characters:
            driver = self.drivers[character]
            if driver is None:
                driver = Stand()
                self.drive(character, driver, now=False)
            request = driver.request(self, character)
            # A finished sequence hands the character on inside request(); label by the driver now in charge.
            labels.append(self.drivers[character].label)
            requests.append(request)
        batch = self.generator.generate(requests, self.time, keep=self.keep)
        self.batches.append((self.clock, len(requests), batch.milliseconds))
        generations = []
        for row, (character, request) in enumerate(zip(characters, requests)):
            frames = int(batch.frames[row])
            transition = max(0, frames - 1 - request.transition_early)
            self.time[character] = 0.0
            self.transition[character] = transition / MODEL_SAMPLE_RATE
            self.planned[character] = self.desired[character]
            self.replan[character] = False
            generations.append(Generation(character, self.clock, frames, transition, labels[row], request, row))
        for listener in self.listeners:
            listener(generations, batch)


__all__ = [
    "Approach",
    "Crowd",
    "CrowdFrame",
    "Driver",
    "Generation",
    "Interact",
    "LOOKAHEAD",
    "Seated",
    "Stand",
    "Walk",
    "sit",
]
